default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows Nt\CurrentVersion\Winlogon' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('PasswordExpiryWarning', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_password_expiry_warning_days)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Microsoft\Windows Nt\CurrentVersion\Winlogon [PasswordExpiryWarning]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows Nt\CurrentVersion\Winlogon')) {
    New-Item -Path 'HKLM:\SOFTWARE\Microsoft\Windows Nt\CurrentVersion\Winlogon' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows Nt\CurrentVersion\Winlogon' -Name 'PasswordExpiryWarning' -Value $ODV_password_expiry_warning_days -PropertyType DWord -Force | Out-Null
exit 0
